<script setup lang="ts">
import { onMounted, ref } from 'vue'
import AppCard from '../../components/AppCard.vue'
import PrimaryButton from '../../components/PrimaryButton.vue'
import { uniApi as uni } from '../../services/platform/uni'
import { healthRepository } from '../../services/api/repositories'
import type { HealthCheckCenter } from '../../types/domain'
const centers = ref<HealthCheckCenter[]>([]); const loading = ref(true); const error = ref('')
onMounted(async () => { try { centers.value = await healthRepository.listHealthCenters() } catch (e) { error.value = (e as Error).message } finally { loading.value = false } })
const choose = (name: string) => uni.showToast({ title: `已选择 ${name}` })
</script>
<template><view class="page centers-page"><view class="topbar"><text class="back" @click="uni.navigateBack()">‹</text><text class="top-title">指定体检中心</text><text class="share">⋯</text></view><AppCard class="intro"><text class="intro-title">先完成基础血液检查</text><text class="muted">检查结果将用于建立健康档案与后续 AI 分析，报告上传后由你确认才会进入正式档案。</text></AppCard><AppCard v-if="error" class="intro"><text class="muted">{{ error }}</text></AppCard><text v-if="loading" class="muted">正在加载体检中心…</text><view class="section-title">推荐体检中心</view><AppCard v-for="center in centers" :key="center.id" class="center-card"><view class="center-head"><text class="center-name">{{ center.name }}</text><text class="distance">{{ center.distanceKm ? center.distanceKm + ' km' : '' }}</text></view><text class="muted">{{ center.address }}</text><text class="items">包含：{{ center.items.join('、') }}</text><view class="center-actions"><text class="phone">☎ {{ center.phone || '到店咨询' }}</text><PrimaryButton label="选择" @click="choose(center.name)" /></view></AppCard><AppCard v-if="!loading && !centers.length" class="tip"><text class="tip-title">暂无指定体检中心</text><text class="muted">请联系平台客服获取检查安排。</text></AppCard><AppCard class="tip"><text class="tip-title">上传报告</text><text class="muted">完成检查后，可从「我的健康 → 体检报告」上传 PDF 或照片。</text></AppCard></view></template>
